import pandas as pd

def max_transaction_each_day(transactions: pd.DataFrame) -> pd.DataFrame:
    transactions["date"] = pd.to_datetime(transactions["day"]).dt.date
    max_per_day = transactions.groupby("date")["amount"].transform("max")
    res = transactions[transactions["amount"] == max_per_day][["transaction_id"]]
    return res.sort_values(by="transaction_id")
